              "text": "With **any of**, **each of**, **either of**, **neither of**, or **none of** and a plural noun we can use a singular or plural verb. However, we prefer a singular verb in careful written English.",
              "vi": "Với any of, each of, either of, neither of hoặc none of và một danh từ số nhiều, ta có thể dùng động từ số ít hoặc số nhiều. Tuy nhiên, trong văn viết cẩn thận ta ưu tiên động từ số ít."
