      "instructionsEn": "Write 3-4 English sentences describing the results of a survey in your class or workplace. Use phrases such as **the majority of**, **the number of**, **none of**, **per cent of**, a subject joined by **either ... or ...** or **neither ... nor ...**, and a quantity such as **ten kilometres** or **fifty pounds** as a subject.",
      "ruleSummary": "Subject-verb agreement (2). With any of, each of, either of, neither of, none of + plural noun, a singular or plural verb is possible, singular preferred in careful writing (Neither of the French athletes has/have won). With a/the majority of, a number of, a lot of, plenty of, all (of), some (of) + plural noun, the verb is plural (A number of refugees have been turned back), but the number of takes a singular verb (The number of books has risen). These quantifiers with an uncountable noun take a singular verb (All the furniture was destroyed). Each/every + singular noun and everyone, everything, anybody, nobody etc. take a singular verb; each after a plural subject keeps a plural verb (The boys have each drawn a picture). Plural measurements, amounts and quantities seen as one thing take a singular verb (The fifty pounds he gave me was soon spent). Items joined by and usually take a plural verb, but a single item such as fish and chips or R and D can be singular. With either...or / neither...nor the verb agrees with the last item (Neither the President nor his representatives are...), with a plural verb possible informally, and either verb possible if the last item is singular after a plural one. Per cent takes a singular verb (2 per cent makes a difference), but a plural verb with of + plural noun (50 per cent of the houses need repairs), and either with a collective noun (80 per cent of the electorate is/are expected). Judge whether each student sentence has correct agreement and is well formed."
