      "instructionsEn": "Write 3-4 English sentences about your family, friends or recent events. Use the possessive with people (**my parents' house**, **James's car**), with time (**last week's meeting**), one sentence with **a friend of my sister's**, and one using **of + noun** for a thing or a process (**the opening of the new library**).",
      "ruleSummary": "The possessive form of nouns. Add 's to singular nouns and irregular plurals (Philip's car, the women's movement) and ' to regular plurals (the boys' boots); names ending in -s can take ' or 's (Derek Jones' / Jones's). The possessive is used with people, groups, living things, places and times, and 's can go on the last word of a noun phrase (the boy on the left's sister). We can say a novel of Jim Kerr's, an uncle of Mark's (or of Mark). The noun after the possessive can be left out for homes, shops and services (We're going to Linda's; the butcher's) or when clear ('Whose hat?' 'Richard's.'). The possessive 's is preferred for particular people (Carolyn's illness) and time (next year's prices, two weeks' holiday); of + noun is preferred for inanimate things (the cover of the book), processes and changes (the destruction of the forest) and long noun phrases (the sister of someone I used to go to school with). Judge whether each student sentence places the apostrophe correctly and chooses a natural possessive or of form."
