      "instructionsEn": "Write 3-4 English sentences describing where you live or work, using at least four compound nouns: a noun + noun combination (**a bus station**), a compound with a measurement (**a ten-minute walk**), an -ing + noun compound (**a swimming pool**) and a noun + -ing compound (**sightseeing**). Remember that the first noun is usually singular.",
      "ruleSummary": "Compound nouns (1). A noun can go in front of another noun to say what something is made of, where it is, when it happens or what someone does (rice pudding, the kitchen cupboard, a night flight, a language teacher); regularly used combinations are compound nouns, sometimes of three nouns (an air-traffic controller). They may be written as one word, two words or with a hyphen. The first noun is usually singular even with a plural meaning (an address book, a car park, not an addresses book), except plural-only nouns or nouns whose plural has a different meaning (a clothes shop, a glasses case, a customs officer, a savings account) and institutions dealing with several items (the publications department, the appointments board). The plural normally goes on the second noun (office-workers, tea leaves), but on the first noun with of or in (birds of prey, commanders-in-chief). Number + noun modifiers are singular (a ten-minute speech, a five-year-old child), though a two-thirds majority and a five-times winner are possible. Compounds can be -ing + noun (a living room, drinking water, a turning-point) or noun + -ing (film-making, risk-taking). Judge whether each student sentence forms its compound nouns correctly and naturally."
