      "ruleSummary": "Compound nouns (2). Instead of noun + noun we often prefer noun + 's + noun when the first noun is the user of the second (a baby's bedroom, a women's clinic), when the second is produced by the first, often an animal (goat's cheese, cow's milk; but lamb chops when the animal is killed), and for parts of people or animals (a woman's face, a giraffe's neck; but noun + noun for parts of things: a pen top, the window frame). We prefer noun + preposition + noun for a container with its contents (a cup of tea vs a tea cup, a box of matches vs a matchbox) and when the combination is not a well-known class of items (a book about cats, not a cat book; a tax on children's clothes, but income tax). Some compound nouns are related to two- and three-word verbs (break out / a break-out, put in / an input, lie down / a lie-down); countable ones form the plural with -s (read-outs, push-ups, outcomes) except a few (lookers-on, runners-up, passers-by, hangers-on). Hyphenated phrases can be placed before nouns (a state-of-the-art computer, day-to-day control, a head-in-the-sand attitude, a four-wheel-drive vehicle). Judge whether each student sentence chooses the natural pattern and forms it correctly."
