      "instructions": "Hãy viết một đoạn ngắn 3-4 câu tiếng Anh kể về một sự việc gần đây (ví dụ một bữa tiệc, một chuyến đi, một lần mua sắm). Dùng **a/an** khi nhắc đến một thứ lần đầu và **the** ở những lần sau (ví dụ **a cake ... the cake**), dùng **the** cho thứ đã rõ từ tình huống (ví dụ **the hotel**, **the beach**), và thêm một câu với **the ... of ...** (ví dụ **the end of the day**, **the price of the tickets**).",
      "instructionsEn": "Write a short paragraph of 3-4 English sentences about something that happened recently (for example a party, a trip or a shopping trip). Use **a/an** when you first mention something and **the** after that (for example **a cake ... the cake**), use **the** for things that are clear from the situation (for example **the hotel**, **the beach**), and add one sentence with **the ... of ...** (for example **the end of the day**, **the price of the tickets**).",
      "ruleSummary": "The and a/an (2): 'things already known'. We use the when we expect the listener or reader to be able to identify the person or thing we mean, and a/an when we don't (Helen's just bought a house / the house in Wilson Street; There's a bus coming / The bus is coming). We also use the when the situation makes clear which one we mean (What do you think of the table?). Something is introduced with a/an on first mention and then referred to with the (a cake and an apple pie ... only the apple pie was eaten; a block of flats ... the building), and the is used even without previous mention if the thing can be understood from what was said (We had a good time on holiday. The hotel was comfortable). Fiction often introduces things with the for suspense (The woman opened the gate). The is often used with a noun followed by an of ... phrase linking it to a particular thing (the meaning of new words, the sound of gunfire; compare a different meaning, a sound like a gunshot), and with nouns such as back, beginning, bottom, end, middle, side, top in the ... of ... (in the middle of his speech). Judge whether each student sentence chooses a/an or the correctly for first mention, shared knowledge and of-phrases."
