              "vi": "Việc ta nói về những người bạn cụ thể (dùng some) hay bạn bè nói chung (không mạo từ), hoặc về một lượng sữa chua có giới hạn nhưng không xác định (dùng some) hay sữa chua nói chung (không mạo từ), không tạo ra khác biệt đáng kể."
