      "ruleSummary": "Some is used with plural and uncountable nouns in affirmative sentences and questions for limited but indefinite quantities (Some furniture arrived for you, not Furniture arrived; weak form /səm/), and for particular but unspecified people or things, meaning 'but not all' (Some teachers never get bored; strong form /sʌm/). Zero article is used with plural and uncountable nouns when talking generally (Furniture is a costly item; Teachers like long holidays; I always like getting good news). Sometimes some and zero article differ very little (I was visiting (some) friends; bring (some) warm clothes). Some before a number means 'approximately' (Some 80% of those eligible voted). Some can replace a/an with a singular noun when we don't know or can't remember which one (some student in class two; some shop or other, not a shop or other). A correct student sentence must not use some for general statements (not Some air is lighter than water when meaning air in general), must not use a bare noun for a limited indefinite quantity in an affirmative sentence where some is needed, and should use some + number correctly for approximation."
