      "instructions": "Đây là các câu trong một lá thư kể về kỳ Giáng sinh. Điền **a/an**, **the** hoặc **-** (không mạo từ) vào chỗ trống cho đúng. (A, B & C)",
      "instructionsEn": "These sentences come from a letter about Christmas. Put **a/an**, **the** or **-** (zero article) in the spaces correctly. (A, B & C)",
