      "instructions": "Hãy viết 3-4 câu tiếng Anh dùng **some**, **any** và các từ ghép của chúng: một câu hỏi mà bạn mong người nghe trả lời 'Có' (**Didn't you get some** ...?), một câu có từ mang nghĩa phủ định như **hardly** hoặc **never** + **any**, một lời mời hoặc lời nhờ với **some**, và một câu dùng **any** với nghĩa 'bất kỳ cái nào cũng được' hoặc **anyone/something/anywhere**.",
      "instructionsEn": "Write 3-4 English sentences using **some**, **any** and their compounds: a question where you expect the answer 'Yes' (**Didn't you get some** ...?), a sentence with a negative-meaning word such as **hardly** or **never** + **any**, an offer or request with **some**, and a sentence using **any** to mean 'it doesn't matter which' or using **anyone/something/anywhere**.",
      "ruleSummary": "Some and any with plural and uncountable nouns for unknown or uncertain amounts. Some is used in affirmative sentences (She had some doubts), in questions expecting agreement or 'Yes' (Didn't John's parents give him some money?), for quite a large amount (The talks went on at some length), for 'not all' (Some people don't like tea), and in offers and requests to sound positive (Shall I send you some details?). Any is used in sentences with a negative meaning, including not, barely, hardly, never, rarely, scarcely, seldom, deny, fail, forbid, prohibit, impossible, unlikely (It was impossible for any air to get out), in other questions (Do you have any better ideas?), to mean 'all of them, it doesn't matter which' (Any of the students could have answered), to mean 'if there are any' (Any questions should be sent to the manager), and commonly in if-clauses. Both can refer to a particular unspecified person or thing (There must be some way I can contact Jo). Compounds someone/anyone, somebody/anybody, something/anything, somewhere/anywhere follow the same rules and take a singular verb (If anybody calls...). Judge whether each student sentence chooses some/any or the compound correctly for its meaning."
