      "instructionsEn": "Write 4 English sentences: two informal ones (as if chatting with friends) using **a lot of**, **lots of** or **plenty of**, and one negative sentence or question with **much** or **many**; then rewrite one of them in an academic style with **much (of)**, **many (of)**, **a great deal of** or **a large number of**.",
      "ruleSummary": "Much (of) is used with uncountable nouns and many (of) with plural nouns; much of can also mean 'a large part of' with a singular countable noun (Much of the national park was destroyed). Much and many can stand without a noun if the meaning is clear. They are mainly used in negative sentences (He didn't show much interest) and questions (How many questions could you answer?). In affirmative sentences, especially in conversation and informal writing, a lot of, lots of or plenty of are preferred; much (of) sounds a little formal and many (of) often very formal or inappropriate (John offered me a lot of money, not much money). In formal contexts such as academic writing, much (of), many (of), a great deal of and a large amount/number of are preferred, and much/many can be pronouns (Much remains to be done; Many have argued...). Much and many are fine in affirmatives after as, so, too (twice as many women; so much spaghetti; I've got too much), but at the end of affirmative sentences we use a lot / lots (not I've got many). Plenty of means 'enough or more than enough', so it is unlikely where that meaning doesn't fit (He's lost a lot of weight, not plenty of), and plenty always needs of before a noun. Judge whether each student sentence uses the right quantifier for the noun type and the formality of the context."
