      "ruleSummary": "All / all of refer to the total number or amount (All (of) my brothers and sisters were there). Negatives normally use not all (Not all the seats were taken, rather than All the seats were not taken); none (of) means not one, a different meaning from not all. Position of all: after the first auxiliary or be (We are all going; They have all heard; These are all confidential files), before a determiner (All (of) their hard work, not Their all hard work), and all four (of the) trees. All alone does not mean everyone/everything (Everyone was waiting, not All were waiting), but all + relative clause means everything (all that he said) and all can mean 'the only thing' (All she wants to do is help). Before singular countable nouns use the whole (of) rather than all (of) the (the whole concert); before plural nouns all (of the) towns means every town while whole towns means some towns completely. Both (of) is used for two things and goes in the same positions as all (They have both finished; both of them; them both); negatives use neither (of) rather than both...not. Judge whether each student sentence uses all, whole, both, neither and none with the right meaning and word order."
