      "ruleSummary": "Each (of) and every go with singular countable nouns to mean all members of a group: each for two or more, every for three or more, and both take a singular verb (every building needs repair). When each follows the noun or pronoun, noun and verb are plural (They are each given...). They/their/them refer back to each soldier, every candidate when gender is not specified. Every is used with almost, nearly, virtually (Almost every visitor, not almost each), for large indefinite groups (every small child), with a number plus plural noun (every six months), in phrases for repeated events (every other, every single, every so often, every few, every now and again), and with abstract nouns chance, confidence, hope, reason, sympathy to mean complete (She has every chance of success). Each stresses individual members (We greeted each guest) and is used for both members of a pair (each (one) weighed over 20 kilos). All + plural/uncountable and every + singular are similar for groups, but for time all weekend means the whole weekend while every weekend means without exception. Everyone = every person, anyone = any person at all (I haven't seen anyone all day). Idioms: every now and again / every once in a while (occasionally), each to their own, every bit as good as, each and every one, every which way. Judge whether each student sentence chooses each, every, all, everyone or anyone correctly with correct agreement."
