      "instructionsEn": "Write 3-4 English sentences: one with **a few** or **a little** (positive) and one with **few** or **little** (negative, formal); one informal sentence with **not many/much** or **a bit of**; and one comparison with **fewer than** or **less than**, or stress a surprisingly large number with **no fewer than / no less than**.",
      "ruleSummary": "Few, a few (of), little, a little (of), less and fewer. (A) few is used with plural countable nouns, (a) little with uncountable nouns. A few / a little are 'positive': a small amount that is enough or more than expected (I've got a few close friends; We had a little money left, so we went out). Few / little are 'negative' and rather formal: not enough, surprisingly low (He has few close friends and often feels lonely; We had little money left). Few/little can follow the, her, my etc. with the negative sense (her few clothes; the little time we have). Few of / a few of / little of / a little of are used before the/my/these or a pronoun. In speech and informal writing not many/much or only a few/little are more usual than few/little (I haven't had much time today), and a bit of is common instead of a little; in academic writing few and little are preferred (Few studies have explored...; The results take little account of...). Less (than) goes with uncountable nouns and fewer (than) with plural countable nouns (less water; fewer lorries), although many people use less with plurals, which some consider incorrect in formal writing. Use less for distances and sums of money; less than or fewer than with percentages; no fewer/less than for a surprisingly large quantity (no fewer than ten managers; profits up by no less than 95%). Judge whether each student sentence chooses the right form for its meaning and style."
