      "instructionsEn": "Write 3-4 English sentences, as in a letter about the place where you live, using quantifiers with and without **of**: for example **many people** / **many of my friends**, **both** / **both of us**, **a few** / **a few of them**, **none** / **none of the shops**. Include at least one sentence with a pronoun (them, us) after the quantifier.",
      "ruleSummary": "Quantifiers with and without of. Quantifiers (some, any, much, many, both, all, each, none, few, little) are used without of directly before a noun (some fresh coffee; many talented young scientists; each item; a few seconds) or alone (could find none), but need of before a pronoun, a determiner or a possessive form before a noun (some of my jewellery; any of these new light bulbs; much of the country; both of my parents; each of you; none of them; little of his money). Many can come between a determiner/possessive and a noun in formal style (his many enemies); much/many can follow this/that (this much money). Many boys (in general) differs from many of the boys (a particular group); all champagne (in general) differs from all (of) the champagne we sell. After personal pronouns use all/both, not all of/both of (I've given them all to Bob; They both need cleaning), while all of them / both of them are also correct. In informal use of can be left out after all/both before the, these, those, my, your etc. (all (of) that cake) but not before them, you, us (or it with all). Each can come before articles and possessives meaning 'each one' (five young elephants, each the size of a car). Judge whether each student sentence uses of correctly with the quantifiers."
