              "vi": "Chúng ta dùng that làm chủ ngữ sau something và anything; sau các từ như all, little, much và none khi dùng như danh từ; và sau so sánh nhất. (Which cũng được dùng làm chủ ngữ sau something và anything nhưng ít phổ biến hơn.) Khi làm tân ngữ sau những từ này, ta dùng that hoặc đại từ quan hệ zero:"
