      "instructionsEn": "Write 3-4 English sentences with defining relative clauses: one where the relative pronoun is the subject (**who/which/that**), one where it is the object and can be left out (zero relative pronoun), and one with **that** after **something**, **all** or a superlative (for example 'the best film **that** I've seen').",
      "ruleSummary": "Defining relative clauses specify which person or thing we mean (The couple who live next to us have sixteen grandchildren), with no comma before them, and are placed as close as possible to the noun they describe. They begin with who (people), which (things) or that (both). When the relative pronoun is the subject, the verb follows it and it cannot be left out (We have a friend who/that plays the piano). When it is the object, a noun or pronoun comes between it and the verb, and it can be left out as a zero relative pronoun (the rocks (which/that) he had brought back; the man (who/that) I met). Whom can replace who as object but is very formal. After something, anything, all, little, much, none (used as nouns) and superlatives, use that as subject (all that remain, not all which remain) and that or zero as object (one of the kindest people (that) I know, not who I know); which after something/anything is possible but less common. Do not add an extra subject or object in the relative clause (The man who gave me the book, not who he gave me; the present that I gave him, not gave him it), and do not repeat the subject with a pronoun in the main clause except in informal speech (My brother who is in the army came to see us). Judge whether each student sentence forms its relative clause correctly."
