              "text": "When we want to add information about the whole or a part of a particular number of things or people we can use a non-defining relative clause with **of which** or **of whom** after words such as all, both, each, many, most, neither, none, part, some, a number (one, two, etc.; the first, the second, etc.; half, a third, etc.) and superlatives (the best, the biggest, etc.):",
