      "instructions": "Hãy viết 3-4 câu tiếng Anh giới thiệu một người hoặc một nơi bạn biết rõ, dùng mệnh đề quan hệ không xác định (có dấu phẩy) với **who**, **which** hoặc **whose**. Thử dùng thêm một mệnh đề với **most of whom / all of which**, hoặc một cụm như **in which case / by which time** (ví dụ: My grandmother, who is 85, still swims every day. She has four children, all of whom live nearby).",
      "instructionsEn": "Write 3-4 English sentences introducing a person or place you know well, using non-defining relative clauses (with commas) with **who**, **which** or **whose**. Also try one clause with **most of whom / all of which**, or a phrase like **in which case / by which time** (for example: My grandmother, who is 85, still swims every day. She has four children, all of whom live nearby).",
      "ruleSummary": "Non-defining relative clauses add extra information that is not needed to identify the noun, and are separated by commas (Valerie Polkoff, who has died aged 90, escaped from Russia in 1917). For people, use who as subject and who or (more formally) whom as object; for things, use which as subject or object (that is best avoided). Which can also refer to the whole preceding situation (The book won't be published until next year, which is disappointing). Whose is possible (Neil Adams, whose parents are both teachers, won first prize). Zero relative pronoun is not possible in a non-defining clause. To talk about all or part of a number of people or things, use all/both/each/many/most/neither/none/some/numbers/superlatives + of whom / of which (a group of men, three of whom were armed; many visits, the most recent of which began today). Phrases at which point/time, by which point/time, during which time and in which case can begin a non-defining clause (It might snow, in which case we won't go). A correct student sentence must use commas, the right pronoun, and no zero pronoun."
