              "text": "Relative clauses beginning with **whatever** (= anything or it doesn't matter what), **whoever** (= the person/group who or any person/group who), or **whichever** (= one thing or person from a limited number of things or people) are used to talk about things or people that are indefinite or unknown:",
              "vi": "Mệnh đề quan hệ bắt đầu bằng **whatever** (= bất cứ thứ gì, cái gì cũng được), **whoever** (= người/nhóm nào, bất kỳ người/nhóm nào) hoặc **whichever** (= một thứ hay một người trong số giới hạn các thứ hay người) được dùng để nói về những vật hoặc người không xác định hay chưa biết:"
