      "instructionsEn": "Write 3-4 English sentences defining some words (for example: orphan, plumber, referendum) using a clause with **whose** or **in which** (for example: An orphan is a child whose parents are dead). Add one sentence using **where/when/why** or **whatever/whoever/whichever**.",
      "ruleSummary": "Whose + noun introduces a relative clause about something belonging to or associated with a person (Stevenson is an architect whose designs have won international praise), in defining or non-defining clauses; it is also used for towns, countries and organisations (Botswana, whose wildlife parks...), and less naturally for particular items. Where, when and whereby work as relative pronouns (the place where we first met; the time when...; the system whereby farmers...), and in formal English preposition + which can replace them (the place at/in which; the date on/by which). Why is used after reason (the reason why I left), or informally that. Who can mean 'the people that' and what 'the thing(s) that' (a list of who's been invited; I didn't know what to do), but what cannot follow a noun (all the books that you asked for, not books what). Whatever (anything), whoever (any person who) and whichever (one from a limited set) begin clauses about indefinite things or people (Whoever wins will play Barcelona). A student definition should use whose + noun or in which correctly."
