      "instructionsEn": "Write 3-4 English sentences describing what you can see around you (in the street, at work, in a photo), using participle clauses after nouns: an **-ing** clause (the man standing by the door), a past participle clause (the car parked outside) and **being + -ed** (the house being built next door).",
      "ruleSummary": "An -ing, past participle (-ed) or being + past participle clause after a noun can replace a defining relative clause: -ing for an active verb (The man driving the bus is my brother = who is driving), past participle or being + -ed for a passive verb (The weapon used in the murder = that was used; The prisoners being released = who are being released). An -ing clause is not possible when a noun comes between the relative pronoun and the verb (the man who Tim is meeting), when the relative clause event comes before the main event and is not its cause (The snow which fell overnight has turned to ice), or for a single completed action (The girl who fell over broke her arm). A past participle clause is not possible when a noun comes between the pronoun and the verb (the speed at which decisions are made) or when the clause has a modal other than will (people who should be asked). A correct student sentence must use these reduced clauses only where they are possible."
